
'use client';

import React, { useEffect, useState, useCallback } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { useForm, Controller, type FieldName } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ArrowLeft, Save, CalendarIcon, Loader2 } from 'lucide-react';
import { Separator } from '@/components/ui/separator';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/lib/supabase/client';
import type { StoredApplication } from '../../[id]/page';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Checkbox } from '@/components/ui/checkbox';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar } from '@/components/ui/calendar';
import { format } from 'date-fns';
import { Textarea } from '@/components/ui/textarea';

// Zod schema for DIN Application - mirrors the creation form
const dinApplicationSchema = z.object({
  title: z.string().optional(),
  firstName: z.string().min(1, "First name is required"),
  middleName: z.string().optional(),
  surname: z.string().min(1, "Surname is required"),
  gender: z.enum(["Male", "Female"], { required_error: "Gender is required" }),
  dateOfBirth: z.date({ required_error: "Date of birth is required" }),
  occupation: z.string().optional(),
  nationality: z.string().optional().default("Nigerian"),
  stateOfOrigin: z.string().optional(),
  localGov: z.string().optional(),
  phone1: z.string().min(1, "Phone 1 is required").regex(/^\+?[0-9\s-()]+$/, "Invalid phone number format"),
  phone2: z.string().regex(/^\+?[0-9\s-()]*$/, "Invalid phone number format").optional().or(z.literal('')),
  phone3: z.string().regex(/^\+?[0-9\s-()]*$/, "Invalid phone number format").optional().or(z.literal('')),
  email: z.string().email("Invalid email address").optional().or(z.literal('')),
  identificationType: z.object({
    internationalPassport: z.boolean().optional(),
    taxIdCard: z.boolean().optional(),
    nationalIdCard: z.boolean().optional(),
    voterRegCard: z.boolean().optional(),
    driversLicense: z.boolean().optional(),
  }).optional().default({}),
  idNumber: z.string().optional(),
  fileNumber: z.string().optional(),
  kdlNumber: z.string().optional(),
  // docCO is handled separately as we don't re-upload files in edit mode for now
  declaration: z.boolean().refine(val => val === true, {
    message: "You must agree to the declaration to submit."
  })
});

// Zod schema for BPO (Building Permit - Organization) - mirrors creation form
const bpoPermitApplicationSchema = z.object({
  kbpNumber: z.string().optional(),
  kdlNumber: z.string().optional(),
  orgName: z.string().min(1, "Name of Organisation is required"),
  cacNumber: z.string().optional(),
  dateOfRegistration: z.date().optional(),
  orgTaxIdNumber: z.string().optional(),
  orgPhone: z.string().min(1, "Organisation phone is required").regex(/^\+?[0-9\s-()]+$/, "Invalid phone number format"),
  orgEmail: z.string().email("Invalid email address").optional().or(z.literal('')),
  ceoTitle: z.string().optional(),
  ceoFirstName: z.string().min(1, "CEO/MD First Name is required"),
  ceoMiddleName: z.string().optional(),
  ceoSurname: z.string().min(1, "CEO/MD Surname is required"),
  ceoDesignation: z.string().optional(),
  ceoPhone: z.string().regex(/^\+?[0-9\s-()]*$/, "Invalid phone number format").optional().or(z.literal('')),
  ceoEmail: z.string().email("Invalid email address").optional().or(z.literal('')),
  ceoIdentificationType: z.object({
    internationalPassport: z.boolean().optional(),
    taxIdCard: z.boolean().optional(),
    nationalIdCard: z.boolean().optional(),
    voterRegCard: z.boolean().optional(),
    driversLicense: z.boolean().optional(),
  }).optional().default({}),
  ceoIdNumber: z.string().optional(),
  orgHouseNo: z.string().optional(),
  orgStreetName: z.string().optional(),
  orgDistrict: z.string().optional(),
  orgCityTown: z.string().optional(),
  orgState: z.string().optional().default("Kaduna"),
  orgCountry: z.string().optional().default("Nigeria"),
  orgPOBox: z.string().optional(),
  orgCO: z.string().optional(),
  orgAdditionalAddressInfo: z.string().optional(),
  repFirstName: z.string().optional(),
  repMiddleName: z.string().optional(),
  repSurname: z.string().optional(),
  repPhone1: z.string().regex(/^\+?[0-9\s-()]*$/, "Invalid phone number format").optional().or(z.literal('')),
  repPhone2: z.string().regex(/^\+?[0-9\s-()]*$/, "Invalid phone number format").optional().or(z.literal('')),
  repEmail: z.string().email("Invalid email address").optional().or(z.literal('')),
  repIdentificationType: z.object({
    internationalPassport: z.boolean().optional(),
    taxIdCard: z.boolean().optional(),
    nationalIdCard: z.boolean().optional(),
    voterRegCard: z.boolean().optional(),
    driversLicense: z.boolean().optional(),
  }).optional().default({}),
  repIdNumber: z.string().optional(),
  plotLandUse: z.string().optional(),
  plotPurpose: z.string().optional(),
  plotDistrict: z.string().optional(),
  plotLGA: z.string().optional(),
  plotDescriptionAddress: z.string().min(1, "Plot Description/Address is required"),
  declaration: z.boolean().refine(val => val === true, {
    message: "You must agree to the declaration to submit the application."
  })
});

type DinApplicationFormValues = z.infer<typeof dinApplicationSchema>;
type BpoPermitApplicationFormValues = z.infer<typeof bpoPermitApplicationSchema>;
type GenericFormValues = DinApplicationFormValues | BpoPermitApplicationFormValues;


const identificationOptions = [
  { id: "internationalPassport" as const, label: "International Passport" },
  { id: "taxIdCard" as const, label: "Tax Identification Card" },
  { id: "nationalIdCard" as const, label: "National ID Card" },
  { id: "voterRegCard" as const, label: "Voter Registration Card" },
  { id: "driversLicense" as const, label: "Driver's License" },
];


function DinEditForm({ application, onSave, isSaving }: { application: StoredApplication, onSave: (data: DinApplicationFormValues) => void, isSaving: boolean }) {
  const { register, handleSubmit, control, formState: { errors }, reset } = useForm<DinApplicationFormValues>({
    resolver: zodResolver(dinApplicationSchema),
    defaultValues: {},
  });

  useEffect(() => {
    // When application data is loaded, populate the form
    if (application.data) {
        const formData = { ...application.data };
        // Convert date string back to Date object for the calendar component
        if (formData.dateOfBirth && typeof formData.dateOfBirth === 'string') {
            formData.dateOfBirth = new Date(formData.dateOfBirth);
        }
        reset(formData);
    }
  }, [application, reset]);
  
  return (
    <form onSubmit={handleSubmit(onSave)}>
      <CardContent className="space-y-8 pt-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div><Label htmlFor="title">Title</Label><Input id="title" {...register("title")} /></div>
            <div className="lg:col-span-1"><Label htmlFor="firstName">First Name*</Label><Input id="firstName" {...register("firstName")} />{errors.firstName && <p className="text-destructive text-xs mt-1">{errors.firstName.message}</p>}</div>
            <div><Label htmlFor="middleName">Middle Name</Label><Input id="middleName" {...register("middleName")} /></div>
            <div><Label htmlFor="surname">Surname*</Label><Input id="surname" {...register("surname")} />{errors.surname && <p className="text-destructive text-xs mt-1">{errors.surname.message}</p>}</div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div><Label>Gender*</Label><Controller name="gender" control={control} render={({ field }) => (<RadioGroup onValueChange={field.onChange} value={field.value} className="flex items-center space-x-4 mt-2"><div className="flex items-center space-x-2"><RadioGroupItem value="Male" id="male" /><Label htmlFor="male" className="font-normal">Male</Label></div><div className="flex items-center space-x-2"><RadioGroupItem value="Female" id="female" /><Label htmlFor="female" className="font-normal">Female</Label></div></RadioGroup>)} />{errors.gender && <p className="text-destructive text-xs mt-1">{errors.gender.message}</p>}</div>
            <div><Label htmlFor="dateOfBirth">Date of Birth*</Label><Controller name="dateOfBirth" control={control} render={({ field }) => (<Popover><PopoverTrigger asChild><Button variant={"outline"} className="w-full justify-start text-left font-normal mt-1"><CalendarIcon className="mr-2 h-4 w-4" />{field.value ? format(field.value, "PPP") : <span>Pick a date</span>}</Button></PopoverTrigger><PopoverContent className="w-auto p-0"><Calendar mode="single" selected={field.value} onSelect={field.onChange} initialFocus /></PopoverContent></Popover>)} />{errors.dateOfBirth && <p className="text-destructive text-xs mt-1">{errors.dateOfBirth.message}</p>}</div>
            <div><Label htmlFor="occupation">Occupation</Label><Input id="occupation" {...register("occupation")} /></div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div><Label htmlFor="phone1">Phone 1*</Label><Input id="phone1" type="tel" {...register("phone1")} />{errors.phone1 && <p className="text-destructive text-xs mt-1">{errors.phone1.message}</p>}</div>
            <div><Label htmlFor="phone2">Phone 2</Label><Input id="phone2" type="tel" {...register("phone2")} /></div>
            <div><Label htmlFor="phone3">Phone 3</Label><Input id="phone3" type="tel" {...register("phone3")} /></div>
        </div>
        <div><Label htmlFor="email">Email</Label><Input id="email" type="email" {...register("email")} />{errors.email && <p className="text-destructive text-xs mt-1">{errors.email.message}</p>}</div>
        <div>
            <Label>Identification</Label>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-x-4 gap-y-2 mt-2">
                {identificationOptions.map(opt => (<div key={opt.id} className="flex items-center space-x-2"><Controller name={`identificationType.${opt.id}`} control={control} render={({ field }) => (<Checkbox id={`applicant_${opt.id}`} checked={!!field.value} onCheckedChange={field.onChange} />)} /><Label htmlFor={`applicant_${opt.id}`} className="font-normal">{opt.label}</Label></div>))}
            </div>
        </div>
        <div><Label htmlFor="idNumber">ID Number</Label><Input id="idNumber" {...register("idNumber")} /></div>
         <Separator />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div><Label htmlFor="fileNumber">File Number</Label><Input id="fileNumber" {...register("fileNumber")} /></div>
            <div><Label htmlFor="kdlNumber">KDL Number</Label><Input id="kdlNumber" {...register("kdlNumber")} /></div>
        </div>
        {application.data.docCO?.name && (
            <div className='text-sm text-muted-foreground'>Uploaded C of O: <span className='font-medium text-foreground'>{application.data.docCO.name}</span> (File uploads cannot be changed)</div>
        )}

      </CardContent>
      <CardFooter className="flex justify-end gap-2">
            <Button type="submit" className="gap-2" disabled={isSaving}>
                {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                Save Changes
            </Button>
        </CardFooter>
    </form>
  );
}


