// A read-only component for application types that are not yet editable
function ReadOnlyApplicationDetails({ data }: { data: Record<string, any> }) {
  const renderValue = (value: any): string | React.ReactNode => {
      if (value instanceof Date) return value.toLocaleDateString();
      if (typeof value === 'boolean') return value ? 'Yes' : 'No';
      if (typeof value === 'object' && value !== null) {
          if (Object.values(value).every(v => typeof v === 'boolean')) {
               const checkedKeys = Object.keys(value).filter(k => (value as any)[k] === true);
               if (checkedKeys.length > 0) return checkedKeys.map(k => k.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())).join(', ') || 'None';
               return 'None';
          }
          if (value.name && value.url) return <a href={value.url} target='_blank' rel='noopener noreferrer' className='text-primary hover:underline'>{value.name}</a>;
          return <pre className="text-xs whitespace-pre-wrap bg-muted p-2 rounded-md">{JSON.stringify(value, null, 2)}</pre>;
      }
      return String(value);
  };

  return (
    <CardContent>
        <p className="p-4 mb-6 text-sm text-center bg-blue-50 border border-blue-200 text-blue-800 rounded-md">
            <strong>Note:</strong> Editing for this application type is not yet implemented. This is a read-only view of the application data.
        </p>
        <dl className="space-y-3 text-sm">
            {Object.entries(data).map(([key, value]) => (
                <div key={key} className="grid grid-cols-1 md:grid-cols-3 gap-1 py-2 border-b">
                    <dt className="font-medium text-muted-foreground">{key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())}</dt>
                    <dd className="md:col-span-2">{renderValue(value)}</dd>
                </div>
            ))}
        </dl>
    </CardContent>
  );
}


export default function EditApplicationPage() {
  const router = useRouter();
  const params = useParams();
  const { toast } = useToast();
  const { id } = params;
  const [application, setApplication] = useState<StoredApplication | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  const fetchApplication = useCallback(async (appId: string) => {
    setLoading(true);
    try {
        const { data, error } = await supabase
            .from('applications')
            .select('*')
            .eq('id', appId)
            .single();

        if (error) throw error;
        setApplication(data as StoredApplication);
    } catch (error) {
        console.error("Error fetching application:", error);
        toast({ title: 'Error', description: 'Failed to fetch application details.', variant: 'destructive' });
    } finally {
        setLoading(false);
    }
  }, [toast]);

  useEffect(() => {
    if (id) {
      fetchApplication(id as string);
    }
  }, [id, fetchApplication]);

  const handleSaveChanges = async (formData: GenericFormValues) => {
    if (!application) return;
    setIsSaving(true);
    
    // Merge new form data with existing application data to preserve fields not in the form
    const updatedData = { ...application.data, ...formData };
    
    let applicantName = application.applicant_name;
    if ('firstName' in formData && 'surname' in formData) {
      applicantName = `${formData.firstName} ${formData.surname}`;
    } else if ('orgName' in formData) {
      applicantName = formData.orgName;
    }

    try {
        const { error } = await supabase
            .from('applications')
            .update({ data: updatedData, applicant_name: applicantName })
            .eq('id', application.id);
        
        if (error) throw error;

        toast({
            title: 'Application Updated',
            description: `Changes for application ${application.data.applicationId || application.id} have been saved.`
        });
        router.back(); // Go back to the previous page

    } catch (error) {
        console.error("Error saving changes:", error);
        toast({
            title: 'Save Error',
            description: error instanceof Error ? error.message : 'Could not save changes to the database.',
            variant: 'destructive',
        });
    } finally {
        setIsSaving(false);
    }
  };

  if (loading) {
    return <div className="text-center p-8">Loading application editor...</div>;
  }
  
  if (!application) {
    return (
      <div className="text-center p-8">
        <h2 className="text-xl font-semibold">Application not found</h2>
        <Button onClick={() => router.back()} variant="link" className="mt-4">Go Back</Button>
      </div>
    );
  }
  
  const renderForm = () => {
    switch (application.type) {
        case 'DIN Application':
            return <DinEditForm application={application} onSave={handleSaveChanges as any} isSaving={isSaving} />;
        case 'Building Permit (Organization)':
            return <BpoEditForm application={application} onSave={handleSaveChanges as any} isSaving={isSaving} />;
        default:
            return <ReadOnlyApplicationDetails data={application.data} />;
    }
  };

  return (
    <div className="space-y-6">
      <Button onClick={() => router.back()} variant="outline" className="gap-2">
        <ArrowLeft className="h-4 w-4" /> Back to Applications
      </Button>

      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">Edit: {application.type}</CardTitle>
          <CardDescription>ID: {application.data.applicationId || application.id}</CardDescription>
        </CardHeader>
        
        {renderForm()}
      </Card>
    </div>
  );
}
